from machine import I2C,UART,Pinfrom  Sengo1  import *import timeimport randomflag = 0# 设置识别点的总行数，根据需要自行修改row = 5# 设置识别点的总列数，根据需要自行修改column = 5num = 0# 等待Sengo1完成操作系统的初始化。此等待时间不可去掉，避免出现Sengo1尚未初始化完毕主控器已经开发发送指令的情况time.sleep(2)# 选择UART或者I2C通讯模式，Sengo1出厂默认为I2C模式，短按模式按键可以切换# 4种UART通讯模式：UART9600（标准协议指令），UART57600（标准协议指令），UART115200（标准协议指令），Simple9600（简单协议指令），# 参看“简单协议指令”# https://tosee.readthedocs.io/zh/latest/Common/Protocol/index.html#section-6########################################################################################################## port = UART(2,rx=Pin(16),tx=Pin(17),baudrate=9600)port = I2C(1,scl=Pin(22),sda=Pin(21),freq=400000)# Sengo1通讯地址：0x60。如果I2C总线挂接多个设备，请避免出现地址冲突sengo1 = Sengo1(0x60)err = sengo1.begin(port)if err != SENTRY_OK:    print(f"Initialization failed，error code:{err}")else:    print("Initialization succeeded")# 1、算法的默认参数设置，如无需更改参数，则可移除本代码块；# 2、只有颜色识别与色块检测两种算法需要设置参数；# 3、Sengo1图像的长宽比为4:3，当宽高值设为3:4时，识别区域为正方形；当宽高值设为1:1时，识别区域为长方形sengo1.SetParam(sengo1_vision_e.kVisionColor,[50, 50, 3, 4, 1])# 1、参考文档# https://tosee.readthedocs.io/zh/latest/Sentry1/Vision/index.html#chapter-vs1-vision-color-index# 2、参考视频（注：Sengo1与Sentry1是两款产品）# https://www.bilibili.com/video/BV1MV4y1f7L2/?spm_id_from=333.1387.upload.video_card.click&vd_source=a6a4a13d17ed26ee248472534a8ec3cc# 3、颜色识别算法常见应用：色块密码盘（魔方的一个面，需要识别点与魔方的每个色块一一对应）；红绿灯识别建议采用色块检测算法# 4、Sengo1每次只能运行一种识别算法；err = sengo1.VisionBegin(sengo1_vision_e.kVisionColor)if err != SENTRY_OK:    print(f"Starting algo Color failed，error code:{err}")else:    print("Starting algo Color succeeded")    def Param_Set():  global row, column, num  # 切换行  for i in range(1, (row + 1), 1):    y = (i * (round((100 / (row + 1)))))    # 切换列    for j in range(1, (column + 1), 1):      num = j + (row * (i - 1))      x = (j * (round((100 / (column + 1)))))      sengo1.SetParam(sengo1_vision_e.kVisionColor,[x, y, 6, 8, 1])      # 等待参数生效后新的识别结果产出，该时间间隔不得低于该算法识别1帧所花费的时间，可以通过算法开启后，屏幕下方的帧率进行推算      time.sleep(0.1)      Display()      def Display():    global num    # Sengo1不主动返回检测识别结果，需要主控板发送指令进行读取。读取的流程：首先读取识别结果的数量，接收到指令后，Sengo1会刷新结果数据，如果结果数量不为零，那么主控再发送指令读取结果的相关信息。请务必按此流程构建程序。    # Sengo最多输出1个识别结果。    obj_num = (sengo1.GetValue(sengo1_vision_e.kVisionColor, sentry_obj_info_e.kStatus))    if obj_num:        if (sengo1.GetValue(sengo1_vision_e.kVisionColor,sentry_obj_info_e.kLabel)==color_label_e.kColorBlack):          print("point%d: Black"%num)        if (sengo1.GetValue(sengo1_vision_e.kVisionColor,sentry_obj_info_e.kLabel)==color_label_e.kColorWhite):          print("point%d: White"%num)        if (sengo1.GetValue(sengo1_vision_e.kVisionColor,sentry_obj_info_e.kLabel)==color_label_e.kColorRed):          print("point%d: Red"%num)        if (sengo1.GetValue(sengo1_vision_e.kVisionColor,sentry_obj_info_e.kLabel)==color_label_e.kColorGreen):          print("point%d: Green"%num)        if (sengo1.GetValue(sengo1_vision_e.kVisionColor,sentry_obj_info_e.kLabel)==color_label_e.kColorBlue):          print("point%d: Blue"%num)        if (sengo1.GetValue(sengo1_vision_e.kVisionColor,sentry_obj_info_e.kLabel)==color_label_e.kColorYellow):          print("point%d: Yellow"%num)    time.sleep(0.2)   while True:    print("Toatlly %d points in this round"%(row*column))    Param_Set()    print("\n")